const e="shared",s="ControlPanel",a=[{id:"start",title:{en:"Getting started",fa:"شروع"}},{id:"logins",title:{en:"Databases and logins",fa:"دیتابیس‌ها و loginها"}},{id:"connect",title:{en:"How apps connect",fa:"اتصال اپ‌ها"}},{id:"backup",title:{en:"Backups",fa:"backup"}},{id:"restore",title:{en:"Restore",fa:"restore"}}],t=[{id:"role",group:"start",title:{en:"One SQL Server for the portfolio",fa:"یک SQL Server برای کل پورتفولیو"},files:["docker-compose.yml","deploy/vps/backup.sh"],en:[{id:"one",h:"One container, many databases",p:["Every app of the portfolio that keeps its data in SQL Server uses one container, `sqlserver`, Microsoft's `mssql/server:2022-latest` image. Like Caddy it has no repo of its own: it is defined in Control Panel's `docker-compose.yml`, the VPS layer changes it, and the scripts around it (databases, logins, backups, restore) are in Control Panel too. Its data is the named volume `sqldata` at `/var/opt/mssql`, so rebuilding or upgrading the container keeps the databases."],examples:["service"]},{id:"dbs",h:"What it holds",p:["On the server it holds Control Panel's `ControlPanelDb` and `HisPlusDemo`, LedgerDashboard, LabFlow and, with the clinic platform, PharmaFlow, FinancePowerApp, ClinicHub's catalog and one database per clinic. The nightly backup names the fixed ones and finds the clinic databases by name, so that list is the practical inventory of the server."],examples:["dbs"]},{id:"health",h:"Healthy, not just started",p:["Its health check runs `sqlcmd ... -Q 'SELECT 1'` inside the container every 5 seconds, up to 30 tries after a 20-second start: SQL Server takes a while to open its databases, and a container that has started is not yet a server that answers. Services that need it wait with `condition: service_healthy`. `$$` in the test passes a literal `$` to the shell, so the password is read from the container's own environment and never written into the compose file. Locally it is published on 14333, so it does not collide with a SQL Server installed on the PC on 1433."],examples:["health"]}],fa:[{id:"one",h:"یک کانتینر، چند دیتابیس",p:["هر اپ پورتفولیو که داده‌اش را در SQL Server نگه می‌دارد از یک کانتینر استفاده می‌کند: `sqlserver`، image مربوط به `mssql/server:2022-latest` از Microsoft. مثل Caddy، repo مخصوص خودش را ندارد: در `docker-compose.yml` کنترل پنل تعریف شده، لایه‌ی VPS تغییرش می‌دهد، و اسکریپت‌های دورش (دیتابیس‌ها، loginها، backup و restore) هم در کنترل پنل هستند. داده‌اش volume نام‌دار `sqldata` در `/var/opt/mssql` است، پس از نو ساختن یا به‌روز کردن کانتینر دیتابیس‌ها را نگه می‌دارد."],examples:["service"]},{id:"dbs",h:"چه چیزی در آن است",p:["روی سرور، `ControlPanelDb` و `HisPlusDemo` کنترل پنل، LedgerDashboard، LabFlow و، با پلتفرم کلینیک، PharmaFlow، FinancePowerApp، catalog مربوط به ClinicHub و یک دیتابیس برای هر کلینیک در آن است. backup شبانه دیتابیس‌های ثابت را با اسم می‌آورد و دیتابیس‌های کلینیک را از روی اسم پیدا می‌کند، پس همان فهرست عملاً سیاهه‌ی سرور است."],examples:["dbs"]},{id:"health",h:"سالم، نه فقط روشن",p:["health check آن هر 5 ثانیه داخل کانتینر `sqlcmd ... -Q 'SELECT 1'` را اجرا می‌کند، تا 30 بار بعد از یک شروع 20 ثانیه‌ای: SQL Server مدتی طول می‌کشد تا دیتابیس‌هایش را باز کند و کانتینری که روشن شده هنوز سروری نیست که جواب بدهد. سرویس‌هایی که لازمش دارند با `condition: service_healthy` صبر می‌کنند. `$$` در این test یک `$` واقعی به shell می‌دهد، پس رمز از environment خود کانتینر خوانده می‌شود و هرگز در فایل compose نوشته نمی‌شود. روی PC روی پورت 14333 منتشر می‌شود تا با SQL Server نصب‌شده روی همان PC در 1433 تداخل نکند."],examples:["health"]}],examples:{service:{title:{en:"The service",fa:"سرویس"},lang:"yaml",file:"docker-compose.yml",from:"  sqlserver:",lines:11},dbs:{title:{en:"The databases backed up",fa:"دیتابیس‌هایی که backup می‌شوند"},lang:"bash",file:"deploy/vps/backup.sh",from:"DATABASES=(",lines:1},health:{title:{en:"The health check",fa:"health check"},lang:"yaml",file:"docker-compose.yml",from:'test: ["CMD-SHELL", "/opt/mssql-tools18',lines:5}},quiz:[{q:{en:"Why do dependent services wait for `service_healthy` rather than for the container to start?",fa:"چرا سرویس‌های وابسته منتظر `service_healthy` می‌مانند نه منتظر روشن شدن کانتینر؟"},options:{en:["SQL Server needs time to open its databases before it answers","Docker cannot start two containers at once","The health check creates the databases"],fa:["SQL Server قبل از جواب دادن زمان لازم دارد تا دیتابیس‌هایش را باز کند","Docker نمی‌تواند دو کانتینر را هم‌زمان روشن کند","health check دیتابیس‌ها را می‌سازد"]},answer:0,why:{en:"Connecting right after start would fail; `SELECT 1` succeeding proves it accepts logins.",fa:"وصل شدن درست بعد از روشن شدن fail می‌شد؛ موفقیت `SELECT 1` نشان می‌دهد login قبول می‌کند."}},{q:{en:"What keeps the databases when the container is recreated?",fa:"وقتی کانتینر از نو ساخته می‌شود چه چیزی دیتابیس‌ها را نگه می‌دارد؟"},options:{en:["The image","The named volume `sqldata` at `/var/opt/mssql`","The nightly backup is restored automatically"],fa:["image","volume نام‌دار `sqldata` در `/var/opt/mssql`","backup شبانه خودکار restore می‌شود"]},answer:1,why:{en:"A container's own filesystem is thrown away; the volume outlives it.",fa:"فایل‌سیستم خود کانتینر دور ریخته می‌شود؛ volume بعد از آن باقی می‌ماند."}},{q:{en:"Why is the test written with `$$MSSQL_SA_PASSWORD`?",fa:"چرا test با `$$MSSQL_SA_PASSWORD` نوشته شده؟"},options:{en:["It is a typo that Compose ignores","It doubles the password strength","Compose turns `$$` into `$`, so the shell in the container reads its own variable"],fa:["یک غلط تایپی است که Compose نادیده می‌گیرد","قدرت رمز را دو برابر می‌کند","Compose `$$` را به `$` تبدیل می‌کند، پس shell داخل کانتینر متغیر خودش را می‌خواند"]},answer:2,why:{en:"A single `$` would be interpolated by Compose from the host's `.env` into the container's configuration.",fa:"یک `$` تنها را Compose از `.env` میزبان در تنظیمات کانتینر جایگزین می‌کرد."}}]},{id:"vps",group:"start",title:{en:"On the VPS",fa:"روی VPS"},files:["deploy/vps/compose.vps.yml","deploy/vps/README.md","deploy/vps/bootstrap.sh"],en:[{id:"layer",h:"No published port",p:["On the VPS `compose.vps.yml` is layered over the base files and changes three things for `sqlserver`. `ports: !reset []` removes the published port: Docker writes its own iptables rules past ufw, so a published port would be open to the internet whatever the firewall says. The apps reach it on Docker's network as `sqlserver,1433`, and an administrator reaches it with `docker compose exec sqlserver ... sqlcmd`, which is what every script here does."],examples:["override"]},{id:"express",h:"Express, with a memory cap",p:["`MSSQL_PID: Express`: the Developer edition is not licensed for anything the public can reach. Express caps a database at 10 GB, far above what is here. `MSSQL_MEMORY_LIMIT_MB` 2048 stops it from taking the memory of every other container; the README sizes the server at 8 GB, with SQL Server alone wanting about 2."],examples:["why"]},{id:"folder",h:"The backup folder, and x86-64",p:["It mounts `/srv/backups/mssql` at `/var/opt/mssql/backup`: the folder through which `backup.sh` and `restore-db.sh` exchange .bak files with the host. SQL Server in the container runs as uid 10001, so `bootstrap.sh` creates that folder owned by 10001 and group-writable for the deploy user. It also refuses an ARM server at once, because the SQL Server image exists only for x86-64."],examples:["uid","arm"]}],fa:[{id:"layer",h:"بدون پورت منتشرشده",p:["روی VPS فایل `compose.vps.yml` روی فایل‌های پایه می‌نشیند و سه چیز را برای `sqlserver` عوض می‌کند. `ports: !reset []` پورت منتشرشده را برمی‌دارد: Docker قانون‌های iptables خودش را از کنار ufw می‌نویسد، پس یک پورت منتشرشده هر چه firewall بگوید به اینترنت باز بود. اپ‌ها روی شبکه‌ی Docker با `sqlserver,1433` به آن می‌رسند و مدیر با `docker compose exec sqlserver ... sqlcmd`، که همه‌ی اسکریپت‌های این‌جا هم همین کار را می‌کنند."],examples:["override"]},{id:"express",h:"Express، با سقف حافظه",p:["`MSSQL_PID: Express`: نسخه‌ی Developer برای هیچ چیزی که عموم به آن دسترسی دارند مجوز ندارد. Express هر دیتابیس را به 10 GB محدود می‌کند که خیلی بیشتر از چیزی است که این‌جا هست. `MSSQL_MEMORY_LIMIT_MB` با مقدار 2048 نمی‌گذارد حافظه‌ی بقیه‌ی کانتینرها را بگیرد؛ README سرور را 8 GB در نظر می‌گیرد که SQL Server به‌تنهایی حدود 2 تای آن را می‌خواهد."],examples:["why"]},{id:"folder",h:"پوشه‌ی backup، و x86-64",p:["پوشه‌ی `/srv/backups/mssql` را در `/var/opt/mssql/backup` mount می‌کند: پوشه‌ای که `backup.sh` و `restore-db.sh` از طریقش فایل‌های .bak را با میزبان رد و بدل می‌کنند. SQL Server داخل کانتینر با uid 10001 اجرا می‌شود، پس `bootstrap.sh` آن پوشه را به مالکیت 10001 و قابل نوشتن برای گروه کاربر deploy می‌سازد. همچنین سرور ARM را همان اول رد می‌کند، چون image مربوط به SQL Server فقط برای x86-64 وجود دارد."],examples:["uid","arm"]}],examples:{override:{title:{en:"The VPS override",fa:"تغییرات VPS"},lang:"yaml",file:"deploy/vps/compose.vps.yml",from:"  sqlserver:",lines:9},why:{title:{en:"Why Express",fa:"چرا Express"},lang:"yaml",file:"deploy/vps/compose.vps.yml",from:"#   - SQL Server runs as Express",lines:2},uid:{title:{en:"The folder for uid 10001",fa:"پوشه برای uid 10001"},lang:"bash",file:"deploy/vps/bootstrap.sh",from:"# SQL Server in its container runs as uid 10001",lines:2},arm:{title:{en:"x86-64 only",fa:"فقط x86-64"},lang:"bash",file:"deploy/vps/bootstrap.sh",from:"# The SQL Server image only exists for x86-64",lines:2}},quiz:[{q:{en:"Why is the SQL Server port removed on the VPS instead of being blocked by ufw?",fa:"چرا پورت SQL Server روی VPS برداشته می‌شود به جای این‌که ufw بلاکش کند؟"},options:{en:["ufw cannot block TCP 1433","Docker's own iptables rules bypass ufw, so a published port is open anyway","Express cannot listen on a port"],fa:["ufw نمی‌تواند TCP 1433 را بلاک کند","قانون‌های iptables خود Docker از ufw رد می‌شوند، پس پورت منتشرشده به‌هرحال باز است","Express نمی‌تواند روی پورت گوش بدهد"]},answer:1,why:{en:"The only safe published port is one that does not exist; apps use Docker's network.",fa:"تنها پورت منتشرشده‌ی امن پورتی است که وجود ندارد؛ اپ‌ها از شبکه‌ی Docker استفاده می‌کنند."}},{q:{en:"Why does the VPS run the Express edition?",fa:"چرا VPS نسخه‌ی Express را اجرا می‌کند؟"},options:{en:["The Developer edition is not licensed for a public-facing server","Express is faster","Express can compress backups"],fa:["نسخه‌ی Developer برای سروری که رو به عموم است مجوز ندارد","Express سریع‌تر است","Express می‌تواند backup را فشرده کند"]},answer:0,why:{en:"Its 10 GB per-database cap is far above the data here; it also cannot compress backups, so gzip does it.",fa:"سقف 10 GB برای هر دیتابیس خیلی بیشتر از داده‌ی این‌جاست؛ backup را هم نمی‌تواند فشرده کند، پس gzip این کار را می‌کند."}}]},{id:"init",group:"logins",title:{en:"Creating the databases",fa:"ساختن دیتابیس‌ها"},files:["docker-compose.yml","db/init.sh","db/01-databases.sql"],en:[{id:"dbinit",h:"A one-shot service",p:['Control Panel\'s databases are created by `db-init`, a one-shot service: the same SQL Server image, used only for its `sqlcmd`, started once `sqlserver` is healthy, with `db/` mounted read-only and `restart: "no"`. `seed-users` waits for it to finish successfully (`service_completed_successfully`), and core-api waits for seed-users, so the start order is a chain of conditions, not sleeps.'],examples:["dbinit"]},{id:"loop",h:"Every script, in order",p:["`init.sh` runs every `db/*.sql` in name order as `sa`, with `-b` so the first SQL error ends it with a failure (and `set -euo pipefail` stops the script). Values are passed as sqlcmd variables (`-v DB_PASSWORD=...`) and the scripts read them as `$(DB_PASSWORD)`, so no password is written in a file in git. The adapters' addresses are passed the same way, so the same seed script works locally (`localhost:4001`) and in Docker (service names)."],examples:["loop"]},{id:"idem",h:"Safe to run again",p:["Every script can run again: `IF DB_ID(...) IS NULL CREATE DATABASE`, tables created only when missing, logins created or else given the current password. So `db-init` can run on every `docker compose up` without harm, and a password changed in `.env` is applied the next time it runs. `HisPlusDemo` holds demo rows only: the adapter that reads it must never be pointed at real hospital data."],examples:["create"]}],fa:[{id:"dbinit",h:"یک سرویس یک‌باره",p:['دیتابیس‌های کنترل پنل را `db-init` می‌سازد، یک سرویس یک‌باره: همان image مربوط به SQL Server، که فقط برای `sqlcmd` آن استفاده می‌شود، وقتی `sqlserver` سالم شد روشن می‌شود، با `db/` که فقط‌خواندنی mount شده و `restart: "no"`. `seed-users` منتظر می‌ماند تا با موفقیت تمام شود (`service_completed_successfully`) و core-api منتظر seed-users است، پس ترتیب شروع زنجیره‌ای از شرط‌هاست، نه sleep.'],examples:["dbinit"]},{id:"loop",h:"همه‌ی اسکریپت‌ها، به ترتیب",p:["`init.sh` همه‌ی `db/*.sql`ها را به ترتیب اسم و با کاربر `sa` اجرا می‌کند، با `-b` تا اولین خطای SQL آن را با شکست تمام کند (و `set -euo pipefail` اسکریپت را متوقف می‌کند). مقدارها به‌صورت متغیر sqlcmd داده می‌شوند (`-v DB_PASSWORD=...`) و اسکریپت‌ها آن‌ها را به شکل `$(DB_PASSWORD)` می‌خوانند، پس هیچ رمزی در فایلی در git نوشته نمی‌شود. آدرس adapterها هم همین‌طور داده می‌شود، پس همان اسکریپت seed هم محلی (`localhost:4001`) کار می‌کند هم در Docker (اسم سرویس‌ها)."],examples:["loop"]},{id:"idem",h:"اجرای دوباره بی‌خطر است",p:["هر اسکریپت را می‌شود دوباره اجرا کرد: `IF DB_ID(...) IS NULL CREATE DATABASE`، جدول‌ها فقط وقتی نیستند ساخته می‌شوند، loginها ساخته می‌شوند یا اگر هستند رمز فعلی را می‌گیرند. پس `db-init` می‌تواند با هر `docker compose up` بی‌ضرر اجرا شود و رمزی که در `.env` عوض شده دفعه‌ی بعد اعمال می‌شود. `HisPlusDemo` فقط ردیف‌های نمایشی دارد: adapterی که آن را می‌خواند هرگز نباید به داده‌ی واقعی بیمارستان وصل شود."],examples:["create"]}],examples:{dbinit:{title:{en:"db-init",fa:"db-init"},lang:"yaml",file:"docker-compose.yml",from:"  db-init:",lines:15},loop:{title:{en:"init.sh",fa:"init.sh"},lang:"bash",file:"db/init.sh",from:"for script in /db/*.sql; do",lines:9},create:{title:{en:"Creating only what is missing",fa:"فقط ساختن چیزی که نیست"},lang:"sql",file:"db/01-databases.sql",from:"-- Creates the two databases",lines:7}},quiz:[{q:{en:"Why are passwords passed with `-v` instead of written in the SQL scripts?",fa:"چرا رمزها با `-v` داده می‌شوند نه این‌که در اسکریپت‌های SQL نوشته شوند؟"},options:{en:["sqlcmd cannot read passwords from files","The scripts are in git; the password stays in `.env`","`-v` encrypts them"],fa:["sqlcmd نمی‌تواند رمز را از فایل بخواند","اسکریپت‌ها در git هستند؛ رمز در `.env` می‌ماند","`-v` آن‌ها را رمزنگاری می‌کند"]},answer:1,why:{en:"The scripts only contain `$(DB_PASSWORD)`; the value arrives at run time.",fa:"اسکریپت‌ها فقط `$(DB_PASSWORD)` دارند؛ مقدار در زمان اجرا می‌رسد."}},{q:{en:"What happens if one of the `db/*.sql` scripts has an error?",fa:"اگر یکی از اسکریپت‌های `db/*.sql` خطا داشته باشد چه می‌شود؟"},options:{en:["`-b` makes sqlcmd fail, init.sh stops, and seed-users never starts","The next script runs anyway","SQL Server restarts"],fa:["`-b` باعث شکست sqlcmd می‌شود، init.sh متوقف می‌شود و seed-users هرگز شروع نمی‌شود","اسکریپت بعدی به‌هرحال اجرا می‌شود","SQL Server دوباره راه می‌افتد"]},answer:0,why:{en:"seed-users needs `service_completed_successfully`, so a failed init blocks the chain.",fa:"seed-users شرط `service_completed_successfully` را دارد، پس init ناموفق زنجیره را می‌بندد."}}]},{id:"logins",group:"logins",title:{en:"Least-privilege logins",fa:"loginهای با کمترین دسترسی"},files:["db/02-service-login.sql","db/03-controlpanel-schema.sql","deploy/vps/make-env.sh"],en:[{id:"svc",h:"controlpanel_svc",p:["core-api and hisplus-adapter never connect as `sa`. They share one SQL login, `controlpanel_svc`, with only what they need: `db_datareader` and `db_datawriter` on ControlPanelDb, with no `db_owner` and no DDL, because the schema comes from the scripts, not from the app; and read-only on HisPlusDemo, all the direct-database adapter needs. If an older version made the login `db_owner`, the script takes that away again."],examples:["svc"]},{id:"deny",h:"DENY beats a role",p:["Finer than roles: the audit log is insert-only for the app. `DENY UPDATE, DELETE ON dbo.AuditLog` wins over the `db_datawriter` grant, so even a bug or an injected query in core-api cannot rewrite who started or stopped a service. A DENY is the one permission SQL Server checks before any grant."],examples:["deny"]},{id:"pw",h:"Generated passwords",p:["The login passwords are generated on the server by `make-env.sh`: letters and digits only, so they never need quoting in `.env`, a `sqlcmd -v` or a connection string, plus a `-Aa1` suffix that meets SQL Server's password policy (`CHECK_POLICY = ON` wants three kinds of character) whatever the random part is. Nobody has to choose them or type them."],examples:["sqlpw"]}],fa:[{id:"svc",h:"controlpanel_svc",p:["core-api و hisplus-adapter هرگز با `sa` وصل نمی‌شوند. یک login مشترک SQL دارند، `controlpanel_svc`، فقط با چیزی که لازم دارند: `db_datareader` و `db_datawriter` روی ControlPanelDb، بدون `db_owner` و بدون DDL، چون schema از اسکریپت‌ها می‌آید نه از اپ؛ و فقط‌خواندنی روی HisPlusDemo، که همه‌ی چیزی است که adapter مستقیم‌خوان دیتابیس لازم دارد. اگر نسخه‌ی قدیمی‌تری login را `db_owner` کرده بود، اسکریپت آن را دوباره پس می‌گیرد."],examples:["svc"]},{id:"deny",h:"DENY از role قوی‌تر است",p:["ریزتر از roleها: لاگ audit برای اپ فقط درج‌کردنی است. `DENY UPDATE, DELETE ON dbo.AuditLog` بر grant مربوط به `db_datawriter` غلبه می‌کند، پس حتی یک باگ یا یک query تزریق‌شده در core-api نمی‌تواند بازنویسی کند چه کسی سرویسی را روشن یا خاموش کرده. DENY تنها مجوزی است که SQL Server قبل از هر grant چک می‌کند."],examples:["deny"]},{id:"pw",h:"رمزهای ساخته‌شده",p:["رمز loginها را `make-env.sh` روی سرور می‌سازد: فقط حرف و عدد، تا هرگز در `.env`، در `sqlcmd -v` یا در connection string به quote نیاز نداشته باشند، به‌اضافه‌ی پسوند `-Aa1` که هر چه بخش تصادفی باشد سیاست رمز SQL Server را برآورده می‌کند (`CHECK_POLICY = ON` سه نوع کاراکتر می‌خواهد). کسی لازم نیست انتخابشان کند یا تایپشان کند."],examples:["sqlpw"]}],examples:{svc:{title:{en:"The service login",fa:"login سرویس"},lang:"sql",file:"db/02-service-login.sql",from:"IF SUSER_ID(N'controlpanel_svc') IS NULL",to:"ALTER ROLE db_datawriter ADD MEMBER controlpanel_svc;"},deny:{title:{en:"An insert-only audit log",fa:"لاگ audit فقط‌درج"},lang:"sql",file:"db/03-controlpanel-schema.sql",from:"-- db_datawriter could otherwise rewrite history",lines:4},sqlpw:{title:{en:"Passwords without quoting",fa:"رمز بدون quote"},lang:"bash",file:"deploy/vps/make-env.sh",from:"# Letters and digits only, so no value ever needs quoting",lines:5}},quiz:[{q:{en:"`controlpanel_svc` is in `db_datawriter`. Can it delete a row of `dbo.AuditLog`?",fa:"`controlpanel_svc` عضو `db_datawriter` است. می‌تواند یک ردیف از `dbo.AuditLog` را حذف کند؟"},options:{en:["Yes, the role allows DELETE","Only through a stored procedure","No, the explicit DENY wins over the role's grant"],fa:["بله، role اجازه‌ی DELETE می‌دهد","فقط از طریق stored procedure","نه، DENY صریح بر grant مربوط به role غلبه می‌کند"]},answer:2,why:{en:"In SQL Server a DENY on an object overrides permissions granted through roles.",fa:"در SQL Server یک DENY روی شیء بر مجوزهایی که از طریق role داده شده غلبه می‌کند."}},{q:{en:"Why does the service login have no DDL rights on ControlPanelDb?",fa:"چرا login سرویس روی ControlPanelDb حق DDL ندارد؟"},options:{en:["The schema is applied by the scripts, so the app never needs to change it","Express does not support DDL","DDL needs a Windows login"],fa:["schema را اسکریپت‌ها اعمال می‌کنند، پس اپ هرگز لازم ندارد عوضش کند","Express از DDL پشتیبانی نمی‌کند","DDL به login ویندوزی نیاز دارد"]},answer:0,why:{en:"A compromised app then cannot drop or alter tables.",fa:"آن‌وقت اپی که نفوذ شده نمی‌تواند جدول‌ها را drop یا alter کند."}}]},{id:"applogins",group:"logins",title:{en:"Logins of the other apps",fa:"loginهای اپ‌های دیگر"},files:["deploy/labflow/sql-login.sql","deploy/clinic/sql-logins.sql"],en:[{id:"labflow",h:"labflow_svc",p:["LabFlow's API runs in a Linux container, which cannot use Windows authentication (what LabFlow uses on the PC), so it gets a SQL login, `labflow_svc`. Read and write, plus `db_ddladmin`, because LabFlow runs its own upgrade scripts (database/050 on) at start-up and they create tables; without it the API crashes on start. `NEXT VALUE FOR` on the accession and MRN sequences needs UPDATE on those sequences, granted one by one rather than on everything."],examples:["labflow"]},{id:"audit",h:"Append-only audit",p:["LabFlow's access log is append-only for the application: `DENY UPDATE, DELETE ON SCHEMA::audit`. PharmaFlow's login gets the same deny on its audit schema, the record of who opened which patient that PHIPA asks for. The deny is on the schema, so a table added to it later is covered without another grant."],examples:["pharma"]},{id:"clinic",h:"The clinic platform",p:["`clinichub_svc` is in the `dbcreator` server role, since ClinicHub creates its catalog and one database per clinic itself with EF migrations; it owns the databases it creates and nothing else on the server. `pharmaflow_svc` and `finance_svc` read and write their own database only; their schema comes from numbered scripts run by migrate.sh, not from the API. Both scripts are idempotent and take passwords as sqlcmd variables; LabFlow's must run again after its `deploy.ps1 -Recreate`, which drops the database and with it the user."],examples:["hub"]}],fa:[{id:"labflow",h:"labflow_svc",p:["API مربوط به LabFlow در یک کانتینر لینوکسی اجرا می‌شود که نمی‌تواند از احراز هویت ویندوز استفاده کند (کاری که LabFlow روی PC می‌کند)، پس یک login SQL می‌گیرد، `labflow_svc`. خواندن و نوشتن، به‌اضافه‌ی `db_ddladmin`، چون LabFlow اسکریپت‌های ارتقای خودش (database/050 به بعد) را هنگام شروع اجرا می‌کند و آن‌ها جدول می‌سازند؛ بدون آن API هنگام شروع crash می‌کند. `NEXT VALUE FOR` روی sequenceهای accession و MRN به UPDATE روی همان sequenceها نیاز دارد که تک‌تک داده می‌شود نه روی همه چیز."],examples:["labflow"]},{id:"audit",h:"audit فقط افزودنی",p:["لاگ دسترسی LabFlow برای اپ فقط افزودنی است: `DENY UPDATE, DELETE ON SCHEMA::audit`. login مربوط به PharmaFlow همین deny را روی schema مربوط به audit خودش می‌گیرد، سابقه‌ی این‌که چه کسی پرونده‌ی کدام بیمار را باز کرده که PHIPA می‌خواهد. deny روی schema است، پس جدولی که بعداً به آن اضافه شود بدون grant دیگری پوشش داده می‌شود."],examples:["pharma"]},{id:"clinic",h:"پلتفرم کلینیک",p:["`clinichub_svc` عضو server role مربوط به `dbcreator` است، چون ClinicHub catalog خودش و یک دیتابیس برای هر کلینیک را خودش با EF migration می‌سازد؛ مالک دیتابیس‌هایی است که می‌سازد و هیچ چیز دیگری روی سرور. `pharmaflow_svc` و `finance_svc` فقط دیتابیس خودشان را می‌خوانند و می‌نویسند؛ schema آن‌ها از اسکریپت‌های شماره‌دار می‌آید که migrate.sh اجرا می‌کند، نه از API. هر دو اسکریپت idempotent هستند و رمزها را به‌صورت متغیر sqlcmd می‌گیرند؛ اسکریپت LabFlow باید بعد از `deploy.ps1 -Recreate` آن دوباره اجرا شود، چون دیتابیس و همراهش user را drop می‌کند."],examples:["hub"]}],examples:{labflow:{title:{en:"labflow_svc",fa:"labflow_svc"},lang:"sql",file:"deploy/labflow/sql-login.sql",from:"IF SUSER_ID(N'labflow_svc') IS NULL",to:"DENY UPDATE, DELETE ON SCHEMA::audit TO labflow_svc;"},pharma:{title:{en:"PharmaFlow's user",fa:"user مربوط به PharmaFlow"},lang:"sql",file:"deploy/clinic/sql-logins.sql",from:"USE PharmaFlow;",to:"DENY UPDATE, DELETE ON SCHEMA::audit TO pharmaflow_svc;"},hub:{title:{en:"ClinicHub may create databases",fa:"ClinicHub می‌تواند دیتابیس بسازد"},lang:"sql",file:"deploy/clinic/sql-logins.sql",from:"IF SUSER_ID(N'clinichub_svc') IS NULL",lines:5}},quiz:[{q:{en:"Why does `labflow_svc` need `db_ddladmin` when the Control Panel login has no DDL at all?",fa:"چرا `labflow_svc` به `db_ddladmin` نیاز دارد، در حالی که login کنترل پنل هیچ DDL ندارد؟"},options:{en:["LabFlow runs its own upgrade scripts at start-up, which create tables","To create its sequences each request","Because Linux containers require it"],fa:["LabFlow هنگام شروع اسکریپت‌های ارتقای خودش را اجرا می‌کند که جدول می‌سازند","برای ساختن sequenceهایش در هر درخواست","چون کانتینرهای لینوکسی این را لازم دارند"]},answer:0,why:{en:"Control Panel's schema comes from db-init; LabFlow migrates itself, so it needs DDL to start.",fa:"schema کنترل پنل از db-init می‌آید؛ LabFlow خودش را migrate می‌کند، پس برای شروع DDL لازم دارد."}},{q:{en:"Why is `clinichub_svc` given `dbcreator`?",fa:"چرا به `clinichub_svc` نقش `dbcreator` داده شده؟"},options:{en:["To back up the other databases","ClinicHub creates one database per clinic itself","To run migrate.sh"],fa:["تا از بقیه‌ی دیتابیس‌ها backup بگیرد","ClinicHub خودش برای هر کلینیک یک دیتابیس می‌سازد","تا migrate.sh را اجرا کند"]},answer:1,why:{en:"It owns what it creates and has no user in the other apps' databases.",fa:"مالک چیزی است که می‌سازد و در دیتابیس بقیه‌ی اپ‌ها user ندارد."}},{q:{en:"The DENY on LabFlow's audit data is on `SCHEMA::audit`, not on one table. What does that give?",fa:"DENY روی داده‌ی audit در LabFlow روی `SCHEMA::audit` است نه یک جدول. این چه چیزی می‌دهد؟"},options:{en:["Faster inserts","Nothing: it is the same as a table DENY","A table added to the schema later is covered too"],fa:["درج سریع‌تر","هیچ: همان DENY روی جدول است","جدولی که بعداً به schema اضافه شود هم پوشش داده می‌شود"]},answer:2,why:{en:"Schema permissions apply to every object in the schema, present and future.",fa:"مجوز schema روی همه‌ی اشیای آن schema اعمال می‌شود، چه حالا چه بعداً."}}]},{id:"migrate",group:"logins",title:{en:"Schemas on every release",fa:"schema در هر انتشار"},files:["deploy/vps/migrate.sh"],en:[{id:"what",h:"Idempotent scripts",p:["Each release runs `migrate.sh` after deploy.sh has pulled the new code: it applies each app's schema scripts to the container SQL Server as `sa`. LedgerDashboard's tables, reader views and reporting schema are applied every time; the scripts are idempotent (they create only what is missing, views are `CREATE OR ALTER`), so a release that changes no schema changes nothing. Data is never touched here: production data lives only on this server."]},{id:"stdin",h:"A host script, run inside",p:["A script on the host is passed to `sqlcmd` inside the container through stdin (`docker compose exec -T`) into a temp file there. So nothing has to be copied into the image or mounted, the temp file belongs to mssql, which can delete it afterwards, and sqlcmd's exit code is passed back so `set -e` stops the release on an error."],examples:["runfile"]},{id:"numbered",h:"Numbered scripts, once each",p:["PharmaFlow and FinancePowerApp do what their `deploy.ps1` does on Windows: numbered scripts (`001_...sql`) each run once, in order, recorded in a table of the database itself (`SchemaMigration`, `ErpMigration`), so the database knows its own version. `-I` turns on quoted identifiers, which filtered indexes need, and `-f 65001` reads the files as UTF-8. Then the clinic logins script and LabFlow's run again, so a rebuilt database gets its users back."],examples:["migratedb"]}],fa:[{id:"what",h:"اسکریپت‌های idempotent",p:["هر انتشار بعد از این‌که deploy.sh کد تازه را pull کرد `migrate.sh` را اجرا می‌کند: اسکریپت‌های schema هر اپ را با `sa` روی SQL Server کانتینر اعمال می‌کند. جدول‌ها، viewهای خواننده و schema گزارش‌گیری LedgerDashboard هر بار اعمال می‌شوند؛ اسکریپت‌ها idempotent هستند (فقط چیزی را که نیست می‌سازند، viewها `CREATE OR ALTER` هستند)، پس انتشاری که schema را عوض نمی‌کند چیزی را عوض نمی‌کند. داده این‌جا هرگز دست نمی‌خورد: داده‌ی production فقط روی همین سرور است."]},{id:"stdin",h:"اسکریپت میزبان، اجرا در داخل",p:["اسکریپتی که روی میزبان است از طریق stdin (`docker compose exec -T`) به یک فایل موقت داخل کانتینر و به `sqlcmd` داده می‌شود. پس لازم نیست چیزی در image کپی یا mount شود، فایل موقت مال mssql است که بعداً می‌تواند پاکش کند، و exit code مربوط به sqlcmd برگردانده می‌شود تا `set -e` انتشار را با خطا متوقف کند."],examples:["runfile"]},{id:"numbered",h:"اسکریپت‌های شماره‌دار، هر کدام یک بار",p:["PharmaFlow و FinancePowerApp همان کاری را می‌کنند که `deploy.ps1` آن‌ها روی ویندوز: اسکریپت‌های شماره‌دار (`001_...sql`) هر کدام یک بار و به ترتیب اجرا می‌شوند و در جدولی در خود دیتابیس ثبت می‌شوند (`SchemaMigration`، `ErpMigration`)، پس دیتابیس نسخه‌ی خودش را می‌داند. `-I` شناسه‌های quote‌دار را روشن می‌کند که filtered indexها لازم دارند و `-f 65001` فایل‌ها را UTF-8 می‌خواند. بعد اسکریپت loginهای کلینیک و LabFlow دوباره اجرا می‌شوند، پس دیتابیسی که از نو ساخته شده userهایش را پس می‌گیرد."],examples:["migratedb"]}],examples:{runfile:{title:{en:"run_sql_file",fa:"run_sql_file"},lang:"bash",file:"deploy/vps/migrate.sh",from:"run_sql_file() {",lines:6},migratedb:{title:{en:"migrate_db",fa:"migrate_db"},lang:"bash",file:"deploy/vps/migrate.sh",from:"  migrate_db() {",to:"    done"}},quiz:[{q:{en:"Why can migrate.sh run on every release even when nothing changed?",fa:"چرا migrate.sh می‌تواند در هر انتشاری اجرا شود حتی وقتی چیزی عوض نشده؟"},options:{en:["It restores a backup first","The scripts create only what is missing, and numbered ones run once","It skips when the git hash is unchanged"],fa:["اول یک backup را restore می‌کند","اسکریپت‌ها فقط چیزی را که نیست می‌سازند و شماره‌دارها یک بار اجرا می‌شوند","وقتی hash مربوط به git عوض نشده رد می‌شود"]},answer:1,why:{en:"Idempotent scripts and a record table make a re-run a no-op.",fa:"اسکریپت‌های idempotent و جدول ثبت، اجرای دوباره را بی‌اثر می‌کنند."}},{q:{en:"How does migrate.sh know a numbered PharmaFlow script was already applied?",fa:"migrate.sh از کجا می‌فهمد یک اسکریپت شماره‌دار PharmaFlow قبلاً اعمال شده؟"},options:{en:["Its name is in the database's `SchemaMigration` table","From a file on the host","By comparing the schema"],fa:["اسمش در جدول `SchemaMigration` همان دیتابیس است","از یک فایل روی میزبان","با مقایسه‌ی schema"]},answer:0,why:{en:"The record travels with the database, so a restored database still knows what it has.",fa:"این ثبت همراه دیتابیس جابه‌جا می‌شود، پس دیتابیس restore‌شده هم می‌داند چه چیزی دارد."}}]},{id:"connect",group:"connect",title:{en:"How apps connect",fa:"اپ‌ها چطور وصل می‌شوند"},files:["docker-compose.yml","services/core-api/src/database/database.service.ts","deploy/vps/compose.vps.yml","deploy/vps/make-clinic-secrets.sh"],en:[{id:"node",h:"Node services: four variables",p:["Inside Docker's network the server's name is the service name, `sqlserver`, port 1433. The Node services get `DB_SERVER`, `DB_NAME`, `DB_USER` and `DB_PASSWORD` as environment, and core-api builds an `mssql` connection pool from them at start; the defaults (localhost, ControlPanelDb, controlpanel_svc) are for running it outside Docker. `trustServerCertificate: true`, because the container's certificate is self-signed and the connection stays on Docker's network."],examples:["pool"]},{id:"dotnet",h:".NET: one connection string",p:[".NET apps take one connection string. On the VPS LabFlow's is `Server=sqlserver,1433;Database=LabFlow;User Id=labflow_svc;...;TrustServerCertificate=True`, with the password interpolated from `.env` by Compose. That works, but it puts the password into the container's environment, where `docker inspect` shows it, which is why the clinic platform does it differently."],examples:["labflow"]},{id:"secrets",h:"Connection strings as files",p:["The clinic platform never puts a password in an environment variable. `make-clinic-secrets.sh` writes each connection string to a file in `/srv/secrets/clinic` (mode 444 in a folder of mode 700, written once and never overwritten), with `sql_cs` building them all the same way, `Encrypt=True` included. Compose mounts each file only into its own service, where .NET reads it as `ConnectionStrings__<name>`; files are read last, so the file wins over the variable of the layers below."],examples:["sqlcs"]}],fa:[{id:"node",h:"سرویس‌های Node: چهار متغیر",p:["داخل شبکه‌ی Docker اسم سرور همان اسم سرویس است، `sqlserver`، پورت 1433. سرویس‌های Node متغیرهای `DB_SERVER`، `DB_NAME`، `DB_USER` و `DB_PASSWORD` را در environment می‌گیرند و core-api هنگام شروع از آن‌ها یک connection pool با `mssql` می‌سازد؛ مقدارهای پیش‌فرض (localhost، ControlPanelDb، controlpanel_svc) برای اجرا بیرون از Docker است. `trustServerCertificate: true`، چون گواهی کانتینر self-signed است و اتصال روی شبکه‌ی Docker می‌ماند."],examples:["pool"]},{id:"dotnet",h:".NET: یک connection string",p:["اپ‌های .NET یک connection string می‌گیرند. روی VPS مال LabFlow این است: `Server=sqlserver,1433;Database=LabFlow;User Id=labflow_svc;...;TrustServerCertificate=True`، که Compose رمزش را از `.env` جایگزین می‌کند. این کار می‌کند، اما رمز را در environment کانتینر می‌گذارد که `docker inspect` نشانش می‌دهد، و برای همین پلتفرم کلینیک آن را جور دیگری انجام می‌دهد."],examples:["labflow"]},{id:"secrets",h:"connection string به‌صورت فایل",p:["پلتفرم کلینیک هرگز رمز را در متغیر environment نمی‌گذارد. `make-clinic-secrets.sh` هر connection string را در یک فایل در `/srv/secrets/clinic` می‌نویسد (با mode 444 در پوشه‌ای با mode 700، یک بار نوشته و هرگز بازنویسی نمی‌شود)، و `sql_cs` همه را به یک شکل می‌سازد، با `Encrypt=True`. Compose هر فایل را فقط در سرویس خودش mount می‌کند که .NET آن را به‌عنوان `ConnectionStrings__<name>` می‌خواند؛ فایل‌ها آخر از همه خوانده می‌شوند، پس فایل بر متغیر لایه‌های پایین‌تر غلبه می‌کند."],examples:["sqlcs"]}],examples:{pool:{title:{en:"core-api's pool",fa:"pool مربوط به core-api"},lang:"typescript",file:"services/core-api/src/database/database.service.ts",from:"this.pool = await new sql.ConnectionPool({",to:"}).connect();"},labflow:{title:{en:"LabFlow on the VPS",fa:"LabFlow روی VPS"},lang:"yaml",file:"deploy/vps/compose.vps.yml",from:"ConnectionStrings__LabFlow:",lines:1},sqlcs:{title:{en:"Connection strings written as secrets",fa:"connection stringها به‌صورت secret"},lang:"bash",file:"deploy/vps/make-clinic-secrets.sh",from:"sql_cs() {",to:"put finance-connection"}},quiz:[{q:{en:"What name does a container use to reach SQL Server on Docker's network?",fa:"یک کانتینر با چه اسمی روی شبکه‌ی Docker به SQL Server می‌رسد؟"},options:{en:["localhost","The VPS's public IP","The service name, `sqlserver`"],fa:["localhost","IP عمومی VPS","اسم سرویس، `sqlserver`"]},answer:2,why:{en:"Compose's network resolves service names; `localhost` inside a container is the container itself.",fa:"شبکه‌ی Compose اسم سرویس‌ها را resolve می‌کند؛ `localhost` داخل کانتینر خود همان کانتینر است."}},{q:{en:"Why does the clinic platform mount connection strings as files instead of environment variables?",fa:"چرا پلتفرم کلینیک connection stringها را به‌صورت فایل mount می‌کند نه متغیر environment؟"},options:{en:[".NET cannot read environment variables","Environment values are visible with `docker inspect`; each file reaches only its own service","Files are faster to read"],fa:[".NET نمی‌تواند متغیر environment بخواند","مقدار environment با `docker inspect` دیده می‌شود؛ هر فایل فقط به سرویس خودش می‌رسد","خواندن فایل سریع‌تر است"]},answer:1,why:{en:"Secrets as files keep passwords out of the container's configuration and out of other services.",fa:"secret به‌صورت فایل رمز را از تنظیمات کانتینر و از بقیه‌ی سرویس‌ها دور نگه می‌دارد."}}]},{id:"pcvps",group:"connect",title:{en:"PC and VPS differ",fa:"تفاوت PC و VPS"},files:["compose.apps.yml","docker-compose.yml","deploy/vps/compose.vps.yml"],en:[{id:"pc",h:"On the PC: the host's SQL Server",p:["On the PC not every app uses the container. LedgerDashboard and LabFlow keep their databases in the SQL Server installed on Windows, which they also use outside Docker; their containers reach it on the host as `host.docker.internal`, mapped with `extra_hosts: host-gateway`. The ledgerdash-adapter reads LedgerDashboard there too, as `ledger_reader`, through its read-only reporting views. So on the PC the container mostly holds Control Panel's own two databases."],examples:["pclabflow","adapter"]},{id:"vps",h:"On the VPS: the container",p:["On the VPS those databases live in the container SQL Server, restored from backups by restore-db.sh, so the VPS layer only changes the address: `DB_SERVER: sqlserver` for ledgerdashboard and the adapter, LabFlow's connection string to `sqlserver,1433`, and `depends_on: sqlserver: condition: service_healthy`, which the base files cannot have, since there the server is outside Compose."],examples:["vpsdep"]},{id:"why",h:"One description per service",p:["Layering keeps one description of each service: the base files say how it is built and configured, the VPS file only what differs there. The local container keeps its port 14333 for tools such as SSMS; on the VPS nothing is published. When a new app moves to the server, the pattern is the same: its database is restored into the container, its login script is run there, and the VPS layer points it at `sqlserver` and waits for it to be healthy."]}],fa:[{id:"pc",h:"روی PC: SQL Server میزبان",p:["روی PC همه‌ی اپ‌ها از کانتینر استفاده نمی‌کنند. LedgerDashboard و LabFlow دیتابیس‌هایشان را در SQL Server نصب‌شده روی ویندوز نگه می‌دارند که بیرون از Docker هم از آن استفاده می‌کنند؛ کانتینرهایشان با `host.docker.internal` به میزبان می‌رسند که با `extra_hosts: host-gateway` تعریف شده. ledgerdash-adapter هم LedgerDashboard را همان‌جا می‌خواند، با `ledger_reader` و از طریق viewهای گزارش فقط‌خواندنی. پس روی PC کانتینر بیشتر همان دو دیتابیس خود کنترل پنل را دارد."],examples:["pclabflow","adapter"]},{id:"vps",h:"روی VPS: کانتینر",p:["روی VPS این دیتابیس‌ها در SQL Server کانتینر هستند که restore-db.sh از backup بازگردانده، پس لایه‌ی VPS فقط آدرس را عوض می‌کند: `DB_SERVER: sqlserver` برای ledgerdashboard و adapter، connection string مربوط به LabFlow به `sqlserver,1433`، و `depends_on: sqlserver: condition: service_healthy` که فایل‌های پایه نمی‌توانند داشته باشند، چون آن‌جا سرور بیرون از Compose است."],examples:["vpsdep"]},{id:"why",h:"یک توصیف برای هر سرویس",p:["لایه‌بندی برای هر سرویس یک توصیف نگه می‌دارد: فایل‌های پایه می‌گویند چطور ساخته و تنظیم می‌شود و فایل VPS فقط چیزی را که آن‌جا فرق دارد. کانتینر محلی پورت 14333 را برای ابزارهایی مثل SSMS نگه می‌دارد؛ روی VPS هیچ چیز منتشر نمی‌شود. وقتی اپ تازه‌ای به سرور منتقل می‌شود الگو همین است: دیتابیسش در کانتینر restore می‌شود، اسکریپت loginش همان‌جا اجرا می‌شود و لایه‌ی VPS آن را به `sqlserver` وصل می‌کند و منتظر سالم شدنش می‌ماند."]}],examples:{pclabflow:{title:{en:"LabFlow on the PC",fa:"LabFlow روی PC"},lang:"yaml",file:"compose.apps.yml",from:"ConnectionStrings__LabFlow:",lines:3},adapter:{title:{en:"The adapter reads the host",fa:"adapter از میزبان می‌خواند"},lang:"yaml",file:"docker-compose.yml",from:"DB_SERVER: host.docker.internal",lines:4},vpsdep:{title:{en:"The VPS points it at the container",fa:"VPS آن را به کانتینر وصل می‌کند"},lang:"yaml",file:"deploy/vps/compose.vps.yml",from:"  ledgerdash-adapter:",lines:8}},quiz:[{q:{en:"Why can't the base `compose.apps.yml` give LabFlow `depends_on: sqlserver`?",fa:"چرا `compose.apps.yml` پایه نمی‌تواند به LabFlow `depends_on: sqlserver` بدهد؟"},options:{en:["On the PC LabFlow's database is on the host's SQL Server, outside Compose","depends_on does not work with .NET","LabFlow has no health check"],fa:["روی PC دیتابیس LabFlow روی SQL Server میزبان و بیرون از Compose است","depends_on با .NET کار نمی‌کند","LabFlow health check ندارد"]},answer:0,why:{en:"Only on the VPS is the database in the container, so only that layer adds the dependency.",fa:"فقط روی VPS دیتابیس در کانتینر است، پس فقط همان لایه وابستگی را اضافه می‌کند."}},{q:{en:"What does `host.docker.internal` reach from a container on the PC?",fa:"`host.docker.internal` از داخل کانتینری روی PC به کجا می‌رسد؟"},options:{en:["The `sqlserver` container","The Windows host itself, where the installed SQL Server runs","The VPS"],fa:["کانتینر `sqlserver`","خود میزبان ویندوز، جایی که SQL Server نصب‌شده اجرا می‌شود","VPS"]},answer:1,why:{en:"`extra_hosts: host-gateway` maps that name to the host's address.",fa:"`extra_hosts: host-gateway` آن اسم را به آدرس میزبان نگاشت می‌کند."}}]},{id:"nightly",group:"backup",title:{en:"The nightly backup",fa:"backup شبانه"},files:["deploy/vps/backup.sh","deploy/vps/install-jobs.sh","deploy/vps/watchdog.sh"],en:[{id:"when",h:"Every night at 03:30",p:["`backup.sh` runs every night at 03:30 server time (UTC, which is 22:30 or 23:30 in Toronto, after the clinics close), from the deploy user's crontab, which `install-jobs.sh` writes. It backs up every SQL Server database, plus Mongo, PostgreSQL and the volumes that hold keys or history, into `/srv/backups/daily/<stamp>`, keeps 14 days, then hands the folder to backup-offsite.sh."],examples:["cron"]},{id:"how",h:"One database at a time",p:["Per database: `BACKUP DATABASE ... WITH INIT, COPY_ONLY, CHECKSUM` into the shared backup folder. `COPY_ONLY` leaves any backup chain alone, `CHECKSUM` verifies each page as it is read. Express cannot compress backups, so the file is read out through the container (it belongs to mssql) and piped through gzip, and the .bak inside is removed. ClinicHub's per-clinic databases are found by name with `LIKE N'ClinicHub[_]%'` (the brackets because `_` alone is a wildcard); a database not on this server is skipped."],examples:["loop","clinicdbs"]},{id:"watch",h:"Failures are visible",p:["`ping_check` tells healthchecks.io when the backup starts, when it succeeds (with its size), and, through `trap ... ERR`, the line where it failed. watchdog.sh, every 5 minutes, also complains when no local backup is younger than 26 hours, so a cron line that silently disappeared is noticed too."],examples:["stale"]}],fa:[{id:"when",h:"هر شب ساعت 03:30",p:["`backup.sh` هر شب ساعت 03:30 به وقت سرور اجرا می‌شود (UTC، که در تورنتو 22:30 یا 23:30 است، بعد از بسته شدن کلینیک‌ها)، از crontab کاربر deploy که `install-jobs.sh` می‌نویسدش. از همه‌ی دیتابیس‌های SQL Server، به‌اضافه‌ی Mongo، PostgreSQL و volumeهایی که کلید یا سابقه نگه می‌دارند، در `/srv/backups/daily/<stamp>` backup می‌گیرد، 14 روز نگه می‌دارد و بعد پوشه را به backup-offsite.sh می‌دهد."],examples:["cron"]},{id:"how",h:"یک دیتابیس در هر بار",p:["برای هر دیتابیس: `BACKUP DATABASE ... WITH INIT, COPY_ONLY, CHECKSUM` در پوشه‌ی مشترک backup. `COPY_ONLY` به هیچ زنجیره‌ی backup دست نمی‌زند و `CHECKSUM` هر صفحه را هنگام خواندن چک می‌کند. Express نمی‌تواند backup را فشرده کند، پس فایل از طریق کانتینر بیرون خوانده می‌شود (مال mssql است) و از gzip رد می‌شود، و .bak داخل کانتینر پاک می‌شود. دیتابیس‌های هر کلینیک ClinicHub با `LIKE N'ClinicHub[_]%'` از روی اسم پیدا می‌شوند (کروشه به این دلیل که `_` تنها wildcard است)؛ دیتابیسی که روی این سرور نیست رد می‌شود."],examples:["loop","clinicdbs"]},{id:"watch",h:"شکست دیده می‌شود",p:["`ping_check` به healthchecks.io خبر می‌دهد که backup کی شروع شد، کی موفق شد (با حجمش)، و از طریق `trap ... ERR` در کدام خط شکست خورد. watchdog.sh هر 5 دقیقه وقتی هیچ backup محلی جوان‌تر از 26 ساعت نباشد هم هشدار می‌دهد، پس خط cronی که بی‌صدا از بین رفته هم دیده می‌شود."],examples:["stale"]}],examples:{cron:{title:{en:"The schedule",fa:"زمان‌بندی"},lang:"bash",file:"deploy/vps/install-jobs.sh",from:"30 3 * * *",lines:2},loop:{title:{en:"Backing up each database",fa:"backup هر دیتابیس"},lang:"bash",file:"deploy/vps/backup.sh",from:'for db in "${DATABASES[@]}"',to:'echo "  $db ok"'},clinicdbs:{title:{en:"The clinic databases, by name",fa:"دیتابیس‌های کلینیک، از روی اسم"},lang:"bash",file:"deploy/vps/backup.sh",from:"mapfile -t clinic_dbs",lines:1},stale:{title:{en:"The watchdog's check",fa:"چک watchdog"},lang:"bash",file:"deploy/vps/watchdog.sh",from:'latest="$(find',lines:2}},quiz:[{q:{en:"Why is the backup piped through gzip instead of using `WITH COMPRESSION`?",fa:"چرا backup از gzip رد می‌شود به جای `WITH COMPRESSION`؟"},options:{en:["gzip is more secure","Express cannot compress backups","COMPRESSION breaks CHECKSUM"],fa:["gzip امن‌تر است","Express نمی‌تواند backup را فشرده کند","COMPRESSION با CHECKSUM ناسازگار است"]},answer:1,why:{en:"Backup compression is not available in the Express edition.",fa:"فشرده‌سازی backup در نسخه‌ی Express در دسترس نیست."}},{q:{en:"Why does the clinic query use `ClinicHub[_]%` instead of `ClinicHub_%`?",fa:"چرا query کلینیک از `ClinicHub[_]%` استفاده می‌کند نه `ClinicHub_%`؟"},options:{en:["In LIKE `_` matches any one character; `[_]` means a real underscore","Brackets make it faster","SQL Server forbids `_` in names"],fa:["در LIKE علامت `_` با هر کاراکتری جور است؛ `[_]` یعنی خود زیرخط","کروشه سریع‌ترش می‌کند","SQL Server `_` را در اسم ممنوع می‌کند"]},answer:0,why:{en:"`ClinicHub_%` would also match a database called `ClinicHubX`.",fa:"`ClinicHub_%` با دیتابیسی به اسم `ClinicHubX` هم جور می‌شد."}},{q:{en:"The crontab line was deleted by mistake. How is it noticed?",fa:"خط crontab اشتباهی پاک شده. چطور فهمیده می‌شود؟"},options:{en:["backup.sh reports it","It is not noticed until a restore is needed","watchdog.sh finds no local backup younger than 26 hours"],fa:["backup.sh گزارشش می‌کند","تا وقتی restore لازم شود فهمیده نمی‌شود","watchdog.sh هیچ backup محلی جوان‌تر از 26 ساعت پیدا نمی‌کند"]},answer:2,why:{en:"A backup that never runs can't report itself; the separate watchdog checks the folder's age.",fa:"backupی که هرگز اجرا نمی‌شود نمی‌تواند خودش را گزارش کند؛ watchdog جداگانه سن پوشه را چک می‌کند."}}]},{id:"offsite",group:"backup",title:{en:"Off the server",fa:"بیرون از سرور"},files:["deploy/vps/backup-offsite.sh"],en:[{id:"why",h:"Surviving the server",p:["The local copy protects against mistakes; only an off-server copy survives losing the server. `backup-offsite.sh`, called by backup.sh with the folder it just wrote, sends that folder and `/srv/secrets` to object storage (OVH, region BHS, so the data stays in Canada) with restic, run from its container: nothing to install on the server."],examples:["restic"]},{id:"restic",h:"Encrypted, deduplicated, thinned",p:["restic encrypts before upload (AES-256, with the key from `RESTIC_PASSWORD`, which is also in the password manager: without it the copies cannot be read), deduplicates, and `forget --keep-daily 14 --keep-weekly 8 --keep-monthly 12 --prune` thins the old snapshots. The night's folder is always mounted at the same path, `/backup/daily`, so every snapshot has the same paths and deduplication works across nights. The backup's own credentials folder is excluded: a copy behind those credentials helps nobody."],examples:["backup"]},{id:"unconfigured",h:"Not configured yet",p:["Without `restic.env` the script says so, reports a failure to healthchecks.io and exits 0: the local backup still counts as done, but the missing off-server copy stays visible every night until it is set up."],examples:["notconf"]}],fa:[{id:"why",h:"زنده ماندن بعد از سرور",p:["کپی محلی در برابر اشتباه محافظت می‌کند؛ فقط کپی بیرون از سرور بعد از از دست رفتن سرور می‌ماند. `backup-offsite.sh` که backup.sh آن را با پوشه‌ای که تازه نوشته صدا می‌زند، آن پوشه و `/srv/secrets` را با restic به object storage می‌فرستد (OVH، منطقه‌ی BHS، تا داده در کانادا بماند)، و restic را از کانتینر خودش اجرا می‌کند: چیزی برای نصب روی سرور نیست."],examples:["restic"]},{id:"restic",h:"رمزنگاری، حذف تکرار، کم کردن",p:["restic قبل از آپلود رمزنگاری می‌کند (AES-256، با کلید `RESTIC_PASSWORD` که در password manager هم هست: بدون آن کپی‌ها خوانده نمی‌شوند)، تکرارها را حذف می‌کند و `forget --keep-daily 14 --keep-weekly 8 --keep-monthly 12 --prune` snapshotهای قدیمی را کم می‌کند. پوشه‌ی هر شب همیشه در یک مسیر ثابت mount می‌شود، `/backup/daily`، پس هر snapshot همان مسیرها را دارد و حذف تکرار بین شب‌ها کار می‌کند. پوشه‌ی اعتبارنامه‌های خود backup کنار گذاشته می‌شود: کپی‌ای که پشت همان اعتبارنامه‌ها باشد به درد کسی نمی‌خورد."],examples:["backup"]},{id:"unconfigured",h:"هنوز تنظیم نشده",p:["بدون `restic.env` اسکریپت همین را می‌گوید، یک شکست به healthchecks.io گزارش می‌دهد و با 0 خارج می‌شود: backup محلی هنوز انجام‌شده حساب می‌شود، اما نبودن کپی بیرون از سرور تا وقتی تنظیم شود هر شب دیده می‌شود."],examples:["notconf"]}],examples:{restic:{title:{en:"restic in its container",fa:"restic در کانتینر خودش"},lang:"bash",file:"deploy/vps/backup-offsite.sh",from:"restic() {",lines:6},backup:{title:{en:"Backup and thinning",fa:"backup و کم کردن"},lang:"bash",file:"deploy/vps/backup-offsite.sh",from:"restic cat config",lines:4},notconf:{title:{en:"When nothing is configured",fa:"وقتی چیزی تنظیم نشده"},lang:"bash",file:"deploy/vps/backup-offsite.sh",from:'if [[ ! -r "$RESTIC_ENV" ]]; then',lines:5}},quiz:[{q:{en:"Why is the night's folder always mounted at `/backup/daily`?",fa:"چرا پوشه‌ی هر شب همیشه در `/backup/daily` mount می‌شود؟"},options:{en:["restic only reads that path","For permissions","Same paths every night let restic deduplicate across snapshots"],fa:["restic فقط آن مسیر را می‌خواند","برای مجوزها","مسیرهای یکسان هر شب به restic اجازه می‌دهد بین snapshotها تکرار را حذف کند"]},answer:2,why:{en:"With a dated path each night would look like new files.",fa:"با مسیر تاریخ‌دار هر شب مثل فایل‌های تازه به نظر می‌رسید."}},{q:{en:"What happens to the backups if `RESTIC_PASSWORD` is lost?",fa:"اگر `RESTIC_PASSWORD` گم شود چه بر سر backupها می‌آید؟"},options:{en:["The off-server copies cannot be read","OVH can reset it","restic falls back to the S3 key"],fa:["کپی‌های بیرون از سرور خوانده نمی‌شوند","OVH می‌تواند reset کند","restic به کلید S3 برمی‌گردد"]},answer:0,why:{en:"The data is encrypted before it leaves; that is why the password is also in the password manager.",fa:"داده قبل از رفتن رمزنگاری می‌شود؛ برای همین رمز در password manager هم هست."}}]},{id:"restore",group:"restore",title:{en:"Restoring a database",fa:"restore یک دیتابیس"},files:["deploy/vps/restore-db.sh"],en:[{id:"what",h:"File name = database name",p:["`restore-db.sh` restores .bak files into the container: every file in `/srv/backups/import`, or the ones named, a nightly `.bak.gz` included (unzipped first). The database name is the file name, checked to be letters, digits and underscores only, since it goes straight into SQL; an existing database of that name is replaced."]},{id:"move",h:"Moving the files",p:["A backup remembers its files' original paths, Windows paths for a database made on the PC, which mean nothing in a Linux container. So `RESTORE FILELISTONLY` lists the logical files and each gets a `MOVE` to `/var/opt/mssql/data/<db>_<n>.mdf`, `.ndf` or `.ldf`. Before restoring, the database is set `SINGLE_USER WITH ROLLBACK IMMEDIATE`, which disconnects the apps, and afterwards back to `MULTI_USER`."],examples:["moves"]},{id:"orphans",h:"Orphaned users",p:["Logins live in master, not in the database, so a restored database's users are orphans: their SIDs match no login on this server. The script drops them and runs each app's own login script again (`ledger_svc` and `ledger_reader`, `labflow_svc`; the clinic ones through migrate.sh, and ClinicHub's databases are handed back to `clinichub_svc` with `ALTER AUTHORIZATION`). Last, it restarts whatever was connected to the old copy, so the apps reconnect to the new one."],examples:["ledger","restart"]}],fa:[{id:"what",h:"اسم فایل = اسم دیتابیس",p:["`restore-db.sh` فایل‌های .bak را در کانتینر restore می‌کند: همه‌ی فایل‌های `/srv/backups/import` یا آن‌هایی که اسمشان داده شود، از جمله یک `.bak.gz` شبانه (که اول از حالت فشرده خارج می‌شود). اسم دیتابیس همان اسم فایل است و چک می‌شود که فقط حرف، عدد و زیرخط باشد، چون مستقیم وارد SQL می‌شود؛ دیتابیس موجود با همان اسم جایگزین می‌شود."]},{id:"move",h:"جابه‌جا کردن فایل‌ها",p:["یک backup مسیر اصلی فایل‌هایش را به خاطر دارد، برای دیتابیسی که روی PC ساخته شده مسیرهای ویندوزی که در یک کانتینر لینوکسی معنایی ندارند. پس `RESTORE FILELISTONLY` فایل‌های منطقی را فهرست می‌کند و هر کدام یک `MOVE` به `/var/opt/mssql/data/<db>_<n>.mdf`، `.ndf` یا `.ldf` می‌گیرد. قبل از restore دیتابیس `SINGLE_USER WITH ROLLBACK IMMEDIATE` می‌شود که اپ‌ها را قطع می‌کند و بعد دوباره `MULTI_USER`."],examples:["moves"]},{id:"orphans",h:"userهای یتیم",p:["loginها در master هستند نه در دیتابیس، پس userهای یک دیتابیس restore‌شده یتیم‌اند: SID آن‌ها با هیچ loginی روی این سرور جور نیست. اسکریپت آن‌ها را drop می‌کند و اسکریپت login خود هر اپ را دوباره اجرا می‌کند (`ledger_svc` و `ledger_reader`، `labflow_svc`؛ مال کلینیک از طریق migrate.sh، و دیتابیس‌های ClinicHub با `ALTER AUTHORIZATION` به `clinichub_svc` برگردانده می‌شوند). در آخر هر چیزی را که به کپی قدیمی وصل بود restart می‌کند تا اپ‌ها به کپی تازه وصل شوند."],examples:["ledger","restart"]}],examples:{moves:{title:{en:"MOVE and REPLACE",fa:"MOVE و REPLACE"},lang:"bash",file:"deploy/vps/restore-db.sh",from:"# One MOVE per file in the backup",to:"ALTER DATABASE [$db] SET MULTI_USER;"},ledger:{title:{en:"Recreating the users",fa:"ساختن دوباره‌ی userها"},lang:"bash",file:"deploy/vps/restore-db.sh",from:"    LedgerDashboard)",lines:5},restart:{title:{en:"Reconnecting the apps",fa:"وصل کردن دوباره‌ی اپ‌ها"},lang:"bash",file:"deploy/vps/restore-db.sh",from:"# Whatever was connected",lines:5}},quiz:[{q:{en:"Why must the app logins be recreated after a restore?",fa:"چرا loginهای اپ باید بعد از restore دوباره ساخته شوند؟"},options:{en:["The restore deletes master","Passwords expire on restore","Logins are in master; the restored users' SIDs match no login here"],fa:["restore دیتابیس master را پاک می‌کند","رمزها با restore منقضی می‌شوند","loginها در master هستند؛ SID userهای restore‌شده با هیچ loginی این‌جا جور نیست"]},answer:2,why:{en:"Dropping the orphaned users and running the login scripts maps them again.",fa:"drop کردن userهای یتیم و اجرای اسکریپت‌های login آن‌ها را دوباره نگاشت می‌کند."}},{q:{en:"Why does every restore need `MOVE` clauses?",fa:"چرا هر restore به عبارت‌های `MOVE` نیاز دارد؟"},options:{en:["The backup holds its original file paths, e.g. Windows paths, which don't exist here","MOVE compresses the files","Express requires it for every restore"],fa:["backup مسیر اصلی فایل‌هایش را دارد، مثلاً مسیر ویندوزی، که این‌جا وجود ندارد","MOVE فایل‌ها را فشرده می‌کند","Express برای هر restore آن را لازم دارد"]},answer:0,why:{en:"Without MOVE SQL Server would try to write to the original paths and fail.",fa:"بدون MOVE، SQL Server سعی می‌کرد در مسیرهای اصلی بنویسد و fail می‌شد."}}]},{id:"restoretest",group:"restore",title:{en:"Proving the backups restore",fa:"اثبات این‌که backupها restore می‌شوند"},files:["deploy/vps/restore-test.sh"],en:[{id:"why",h:"Once a month",p:["A backup nobody has restored is a hope. On the 1st of each month at 05:00, restore-test.sh proves the off-server copy restores. `restic check --read-data-subset=10%` downloads a tenth of the data and verifies its checksums (all of it over about a year), then the latest nightly snapshot is restored into a scratch folder under the SQL Server backup mount, where the container can read it."],examples:["check"]},{id:"dbs",h:"Every database, under another name",p:["Every database in it is restored under another name, `RestoreTest_<name>`, with `CHECKSUM`, checked with `DBCC CHECKDB ... WITH NO_INFOMSGS, ALL_ERRORMSGS`, its tables counted, and dropped again. Nothing in use is touched. Then IntegrationHub's dump is listed with `pg_restore`, every archive is tested with `gzip -t`, and the clinic secrets are checked to be there and not empty."],examples:["test"]},{id:"report",h:"Which step failed",p:["`step` names what is running, so the `ERR` trap reports to healthchecks.io exactly which step failed. An `EXIT` trap removes the scratch folder through a container, because restic wrote it as root and the deploy user could not delete it."],examples:["traps"]}],fa:[{id:"why",h:"ماهی یک بار",p:["backupی که هیچ کس restoreش نکرده فقط یک امید است. روز اول هر ماه ساعت 05:00، restore-test.sh ثابت می‌کند که کپی بیرون از سرور restore می‌شود. `restic check --read-data-subset=10%` یک دهم داده را دانلود می‌کند و checksumهایش را چک می‌کند (در حدود یک سال همه‌اش)، و بعد آخرین snapshot شبانه در یک پوشه‌ی موقت زیر mount مربوط به backup در SQL Server restore می‌شود، جایی که کانتینر می‌تواند بخواندش."],examples:["check"]},{id:"dbs",h:"هر دیتابیس، با اسم دیگر",p:["هر دیتابیس داخل آن با اسم دیگری restore می‌شود، `RestoreTest_<name>`، با `CHECKSUM`، با `DBCC CHECKDB ... WITH NO_INFOMSGS, ALL_ERRORMSGS` چک می‌شود، جدول‌هایش شمرده می‌شوند و دوباره drop می‌شود. به هیچ چیز در حال استفاده دست زده نمی‌شود. بعد dump مربوط به IntegrationHub با `pg_restore` فهرست می‌شود، هر آرشیو با `gzip -t` تست می‌شود و چک می‌شود که secretهای کلینیک هستند و خالی نیستند."],examples:["test"]},{id:"report",h:"کدام قدم شکست خورد",p:["`step` اسم کاری است که در حال اجراست، پس trap مربوط به `ERR` دقیقاً به healthchecks.io می‌گوید کدام قدم شکست خورد. یک trap روی `EXIT` پوشه‌ی موقت را از طریق یک کانتینر پاک می‌کند، چون restic آن را با root نوشته و کاربر deploy نمی‌توانست پاکش کند."],examples:["traps"]}],examples:{check:{title:{en:"A tenth each month",fa:"یک دهم در هر ماه"},lang:"bash",file:"deploy/vps/restore-test.sh",from:"# A tenth of the data",lines:2},test:{title:{en:"Restore, check, drop",fa:"restore، چک، drop"},lang:"bash",file:"deploy/vps/restore-test.sh",from:"IF DB_ID(N'$test_db') IS NOT NULL DROP DATABASE",lines:6},traps:{title:{en:"Cleaning up as root",fa:"پاک‌سازی با root"},lang:"bash",file:"deploy/vps/restore-test.sh",from:"cleanup() {",lines:3}},quiz:[{q:{en:"Why are the test databases named `RestoreTest_<name>`?",fa:"چرا دیتابیس‌های تست `RestoreTest_<name>` نام‌گذاری می‌شوند؟"},options:{en:["restic requires a prefix","So the databases in use are never replaced","DBCC only checks prefixed names"],fa:["restic پیشوند لازم دارد","تا دیتابیس‌های در حال استفاده هرگز جایگزین نشوند","DBCC فقط اسم‌های پیشونددار را چک می‌کند"]},answer:1,why:{en:"The test runs on the live server; a different name keeps it beside, not over, the real data.",fa:"تست روی سرور واقعی اجرا می‌شود؛ اسم دیگر آن را کنار داده‌ی واقعی نگه می‌دارد نه رویش."}},{q:{en:"What does `--read-data-subset=10%` trade off?",fa:"`--read-data-subset=10%` چه چیزی را با چه عوض می‌کند؟"},options:{en:["It checks only one database","It skips encryption","Less download each month, while all data is read over about a year"],fa:["فقط یک دیتابیس را چک می‌کند","رمزنگاری را رد می‌کند","دانلود کمتر در هر ماه، در حالی که همه‌ی داده در حدود یک سال خوانده می‌شود"]},answer:2,why:{en:"Each month a different tenth is verified against its checksums.",fa:"هر ماه یک دهم دیگر با checksumهایش چک می‌شود."}}]},{id:"export",group:"restore",title:{en:"Moving databases from the PC",fa:"انتقال دیتابیس از PC"},files:["deploy/vps/export-dbs.ps1","deploy/vps/README.md"],en:[{id:"move",h:"export, scp, restore",p:["The first deploy moved LedgerDashboard and LabFlow from the PC. `export-dbs.ps1` backs them up from the local SQL Server with Windows authentication (`sqlcmd -E`, no admin needed), `COPY_ONLY` so it does not disturb any backup chain on the PC, and `CHECKSUM`. Then `scp` copies the files to `/srv/backups/import/`, and on the server `docker compose up -d --wait sqlserver` starts the database alone and waits until it is healthy before `restore-db.sh` runs."],examples:["steps"]},{id:"folder",h:"Through Public Documents",p:["The SQL Server service writes the .bak, not you, and its own Backup folder is not readable without admin rights. So the script writes to Public Documents, which the service can write and you can read, copies the file to `deploy/vps/export`, and removes the copy there."],examples:["ps"]},{id:"after",h:"Before and after",p:["restore-db.sh recreates `ledger_svc`, `ledger_reader` and `labflow_svc` with the passwords from the two `.env` files, so those must be filled in first. Control Panel's own databases are not moved: `db-init` creates them on the first deploy. The same restore-db.sh later restores a nightly backup too, given its path in `/srv/backups/daily/<stamp>/`. Remove the .bak files from the import folder afterwards: the next run without arguments would restore them again and replace the live database."]}],fa:[{id:"move",h:"export، scp، restore",p:["اولین استقرار LedgerDashboard و LabFlow را از PC منتقل کرد. `export-dbs.ps1` از آن‌ها روی SQL Server محلی با احراز هویت ویندوز backup می‌گیرد (`sqlcmd -E`، بدون نیاز به admin)، با `COPY_ONLY` تا به هیچ زنجیره‌ی backup روی PC دست نزند، و `CHECKSUM`. بعد `scp` فایل‌ها را به `/srv/backups/import/` کپی می‌کند و روی سرور `docker compose up -d --wait sqlserver` فقط دیتابیس را روشن می‌کند و تا سالم شدنش صبر می‌کند، بعد `restore-db.sh` اجرا می‌شود."],examples:["steps"]},{id:"folder",h:"از طریق Public Documents",p:["سرویس SQL Server فایل .bak را می‌نویسد نه تو، و پوشه‌ی Backup خودش بدون دسترسی admin خواندنی نیست. پس اسکریپت در Public Documents می‌نویسد که سرویس می‌تواند در آن بنویسد و تو می‌توانی بخوانی، فایل را به `deploy/vps/export` کپی می‌کند و کپی آن‌جا را پاک می‌کند."],examples:["ps"]},{id:"after",h:"قبل و بعد",p:["restore-db.sh `ledger_svc`، `ledger_reader` و `labflow_svc` را با رمزهای دو فایل `.env` دوباره می‌سازد، پس این‌ها باید اول پر شده باشند. دیتابیس‌های خود کنترل پنل منتقل نمی‌شوند: `db-init` در اولین استقرار آن‌ها را می‌سازد. همان restore-db.sh بعداً یک backup شبانه را هم restore می‌کند، اگر مسیرش در `/srv/backups/daily/<stamp>/` داده شود. بعد از آن فایل‌های .bak را از پوشه‌ی import پاک کن: اجرای بعدی بدون آرگومان دوباره restoreشان می‌کرد و دیتابیس در حال استفاده را جایگزین می‌کرد."]}],examples:{steps:{title:{en:"On the server",fa:"روی سرور"},lang:"bash",file:"deploy/vps/README.md",from:"docker compose up -d --wait sqlserver",lines:3},ps:{title:{en:"Backing up on Windows",fa:"backup روی ویندوز"},lang:"powershell",file:"deploy/vps/export-dbs.ps1",from:"foreach ($db in $Databases) {",lines:8}},quiz:[{q:{en:"Why does export-dbs.ps1 write the .bak to Public Documents first?",fa:"چرا export-dbs.ps1 فایل .bak را اول در Public Documents می‌نویسد؟"},options:{en:["scp only reads from there","The SQL Server service writes it, and its own Backup folder needs admin to read","Windows forbids backups elsewhere"],fa:["scp فقط از آن‌جا می‌خواند","سرویس SQL Server آن را می‌نویسد و پوشه‌ی Backup خودش برای خواندن admin می‌خواهد","ویندوز backup در جای دیگر را ممنوع می‌کند"]},answer:1,why:{en:"Public Documents is writable by the service and readable by the user.",fa:"Public Documents برای سرویس قابل نوشتن و برای کاربر قابل خواندن است."}},{q:{en:"Why `--wait` in `docker compose up -d --wait sqlserver` before restoring?",fa:"چرا قبل از restore از `--wait` در `docker compose up -d --wait sqlserver` استفاده می‌شود؟"},options:{en:["So restore-db.sh runs only once SQL Server is healthy","To wait for the scp","It waits for the other apps to stop"],fa:["تا restore-db.sh فقط وقتی SQL Server سالم شد اجرا شود","برای صبر کردن تا scp","صبر می‌کند تا بقیه‌ی اپ‌ها متوقف شوند"]},answer:0,why:{en:"`--wait` returns when the service's health check passes.",fa:"`--wait` وقتی health check سرویس موفق شد برمی‌گردد."}}]}],o={project:e,repo:s,groups:a,pages:t};export{o as default,a as groups,t as pages,e as project,s as repo};
